def task_func(ftp_server='ftp.dlptest.com', ftp_user='dlpuser', ftp_password='rNrKYTX9g7z3RgJRmxWuGHbeu', ftp_dir='/ftp/test'):
    """
    Downloads all files from a specific directory on an FTP server using wget in a subprocess.
    """
    ftp = ftplib.FTP()
    try:
        try:
            ftp.connect(ftp_server)
        except Exception as e:
            raise Exception(f"Failed to connect to FTP server {ftp_server}: {str(e)}")

        try:
            ftp.login(ftp_user, ftp_password)
        except Exception as e:
            raise Exception(f"Failed to log into FTP server {ftp_user} with user {ftp_user}: {str(e)}")

        try:
            ftp.cwd(ftp_dir)
        except Exception as e:
            raise Exception(f"Failed to change to directory {ftp_dir} on server {ftp_server}: {str(e)}")

        filenames = ftp.nlst()
        attempted_downloads = []

        for filename in filenames:
            if not filename or filename in ('.', '..'):
                continue

            local_name = os.path.basename(filename) or filename
            attempted_downloads.append(local_name)

            # Constructing URL with credentials directly to avoid issues with some wget versions 
            # and passing parameters via command line args.
            ftp_url = f"ftp://{ftp_user}:{ftp_password}@{ftp_server}{ftp_dir.rstrip('/')}/{local_name}"
            cmd = [
                "wget",
                "--no-passive-ftp",
                ftp_url
            ]
            subprocess.run(cmd, check=False)

        return attempted_downloads
    finally:
        try:
            ftp.quit()
        except Exception:
            try:
                ftp.close()
            except Exception:
                pass

