import threading

def task_func(ip_range, port):
    """
    Scans a specified IP address range and checks if a specified port is open on each IP.
    Returns a dictionary with IP addresses as keys and a boolean indicating the port's status.
    """
    if not isinstance(ip_range, str) or not ip_range.strip():
        return {}
    if isinstance(port, bool) or not isinstance(port, int) or port <= 0 or port > 65535:
        return {}

    try:
        network = IPv4Network(ip_range, strict=False)
    except Exception:
        return {}

    results = {}
    lock = threading.Lock()

    def scan_ip(ip):
        ip_str = str(ip)
        is_open = False
        sock = None
        try:
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.settimeout(0.5)
            # connect_ex returns 0 if connection succeeds
            is_open = sock.connect_ex((ip_str, port)) == 0
        except Exception:
            is_open = False
        finally:
            if sock is not None:
                try:
                    sock.close()
                except Exception:
                    pass
        with lock:
            results[ip_str] = is_open

    threads = []
    # Use a thread pool limit to prevent resource exhaustion on large ranges
    max_threads = 100

    for ip in network.hosts():
        t = Thread(target=scan_ip, args=(ip,))
        threads.append(t)
        t.start()

        # If we hit the max_threads limit, wait for them to finish before starting new ones
        if len(threads) >= max_threads:
            for thread in threads:
                thread.join()
            threads = [] # Reset the list for the next batch

    # Wait for any remaining threads to finish
    for thread in threads:
        thread.join()

    return results

