        pd.tseries.frequencies.to_offset(freq)
    except Exception:
        raise ValueError("freq must be a valid frequency string.")

    if df.empty:
        raise ValueError("df must not be empty.")

    value_series = df["value"]
    # Check if numeric (handling bool edge case: type(True) == int)
    if value_series.dtype == bool or not pd.api.types.is_numeric_dtype(value_series):
        raise ValueError("'value' column must contain numeric, non-boolean data.")

    if value_series.isna().any():
        raise ValueError("'value' column must not contain missing values.")

    if decomposition_model == "multiplicative" and (value_series <= 0).any().any(): # Added .any() for full series check
        raise ValueError("For multiplicative decomposition, 'value' must contain only positive values.")

    ts = df.copy()

    # Ensure datetime handling
    if isinstance(ts.index, pd.DatetimeIndex):
        datetime_index = ts.index
    elif "date" in ts.columns:
        try:
            datetime_index = pd.to_datetime(ts["date"])
        except Exception:
            raise ValueError("The 'date' column must contain valid datetime values.")
    else:
        raise ValueError("df must have a DatetimeIndex or a 'date' column.")

    if datetime_index.isna().any():
        raise ValueError("Datetime index or 'date' column contains invalid dates.")

    ts.index = pd.DatetimeIndex(datetime_index)
    ts = ts.sort_index()

    try:
        ts = ts.asfreq(freq)
    except Exception:
        raise ValueError("freq must be a valid frequency string.")

    if ts["value"].isna().any():
        raise ValueError("Time series contains missing values after applying the specified frequency.")

    # Period logic
    period_map = {
        "B": 5, "D": 7, "W": 52, "M": 12, "Q": 4, "A": 1, "Y": 1, "H": 24, "T": 60, "min": 60, "S": 60,
    }

    offset = pd.tseries.frequencies.to_offset(freq)
    # Get base frequency string name (e.g., 'D', 'H', 'W-SUN')
    freq_name = offset.name
    # Handle aliases like 'W-MON' -> 'W'
    base_freq = freq_name.split('-')[0]

    period = period_map.get(base_freq)

    if period is None:
        raise ValueError("Unable to infer a suitable seasonal period from freq.")

    if len(ts) < 2 * period:
        raise ValueError("Time series must contain at least two full seasonal cycles for decomposition.")

    result = seasonal_decompose(ts["value"], model=decomposition_model, period=period)
    fig = result.plot()
    axes = fig.axes
    plt.tight_layout()

    return result, axes

