    def sanitize_folder_name(name):
        name = name.strip()
        name = re.sub(r'[<>:"/\\|?*\x00-\x1f]', "_", name)
        name = re.sub(r"\s+", " ", name).strip()
        name = name.rstrip(". ")
        return name

    def first_text_outside_brackets(filename):
        base_name = os.path.splitext(filename)[0]
        # Regex to split on brackets and match text outside
        parts = re.split(r"\[[^\[\]]*\]", base_name)
        for part in parts:
            match = re.search(r"[^\s\-_\.]+(?:[ \-_\.]+[^\s\-_\.]+)*", part)
            if match:
                text = match.group(0).strip(" -_.")
                if text:
                    return text
        return None

    result = {}

    try:
        entries = os.listdir(directory)
    except Exception:
        return (directory, {})

    for entry in entries:
        source_path = os.path.join(directory, entry)

        if not os.path.isfile(source_path):
            continue

        folder_key = first_text_outside_brackets(entry)
        if not folder_key:
            continue

        folder_name = sanitize_folder_name(folder_key)
        if not folder_name:
            continue

        target_dir = os.path.join(directory, folder_name)
        os.makedirs(target_dir, exist_ok=True)

        target_path = os.path.join(target_dir, entry)

        if os.path.abspath(source_path) == os.path.abspath(target_path):
            result.setdefault(folder_name, []).append(os.path.basename(target_path))
            continue

        if os.path.exists(target_path):
            stem, ext = os.path.splitext(entry)
            timestamp = datetime.now().strftime("%Y%m%d%H%M%S%f")
            target_path = os.path.join(target_dir, f"{stem}_{timestamp}{ext}")

        shutil.move(source_path, target_path)
        result.setdefault(folder_name, []).append(os.path.basename(target_path))

    return (directory, result)

