    keyword_pattern = re.compile(r"\b(like|what)\b", flags=re.IGNORECASE)
    filtered_df = df[df["Title"].fillna("").astype(str).str.contains(keyword_pattern, na=False, regex=True)]

    word_freq = {}

    for content in filtered_df["Content"].fillna("").astype(str):
        tokens = nltk.word_tokenize(content)
        for token in tokens:
            if token in punctuation:
                continue
            if all(char in punctuation for char in token):
                continue
            word = token.lower()
            word_freq[word] = word_freq.get(word, 0) + 1

    return word_freq

