import os
from flask_mail import Mail
def task_func(app_name):
    """
    Initializes a Flask-Mail instance for sending emails using the generated Flask application 
    with the specified app_name. Email configuration is retrieved from environment variables.
    """
    def _parse_bool(value, default=False):
        if value is None:
            return default
        if isinstance(value, bool):
            return value
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            return bool(value)
        value = str(value).strip().lower()
        if value in {"1", "true", "t", "yes", "y", "on"}:
            return True
        if value in {"0", "false", "f", "no", "n", "off", ""}:
            return False
        return default

    def _parse_int(value, default):
        if value is None:
            return default
        if isinstance(value, bool):
            return default
        if isinstance(value, int):
            return value
        try:
            return int(str(value).strip())
        except (TypeError, ValueError):
            return default

    app = Flask(app_name)

    mail_config = {
        "MAIL_SERVER": os.environ.get("MAIL_SERVER", "localhost"),
        "MAIL_PORT": _parse_int(os.environ.get("MAIL_PORT"), 25),
        "MAIL_USE_TLS": _parse_bool(os.environ.get("MAIL_USE_TLS"), False),
        "MAIL_USERNAME": os.environ.get("MAIL_USERNAME"),
        "MAIL_PASSWORD": os.environ.get("MAIL_PASSWORD"),
    }

    app.config.update(mail_config)
    mail = Mail(app)

    return mail, mail_config

