import glob
import os
from openpyxl import load_workbook
def task_func(directory_path='./xlsx_files/'):
    if not isinstance(directory_path, str) or not os.path.exists(directory_path):
        return 0

    file_paths = glob.glob(os.path.join(directory_path, '*.xlsx'))
    processed_count = 0

    for file_path in file_paths:
        if not os.path.isfile(file_path):
            continue
        try:
            workbook = load_workbook(file_path)
            modified = False

            for sheet in workbook.worksheets:
                for row in sheet.iter_rows():
                    for cell in row:
                        value = cell.value
                        if isinstance(value, str):
                            # Protect " by prefixing with \\" (meaning a single double quote becomes a backslash + double quote)
                            new_value = re.sub(r'"', r'\\"', value)
                            if new_value != value:
                                cell.value = new_value
                                modified = True

            if modified:
                workbook.save(file_path)

            processed_count += 1
        except Exception:
            # Skip files that cannot be processed (e.g., corrupted or locked)
            continue

    return processed_count
